      const p = parseFloat(t) || 0, saldo = Number(G.saldo ? G.saldo() : 0) || 0, basta = !soldi || saldo >= p - 1e-9;
      nuovo.querySelectorAll('.mg-f').forEach(b => b.classList.toggle('sel', b.dataset.f === t));
      targa.innerHTML = `<span class="oro"><small>${L('posta', 'stake')}</small>${eur(p)}</span><span><small>${L('piatto fino a', 'pot up to')}</small>${eur(p * (sq ? 4 : n))}</span><span class="${basta ? '' : 'no'}"><small>${L('saldo', 'balance')}</small>${eur(saldo)}</span>`;
